// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function testFuzz_property(uint256 nonce, address filler1, address filler2) public {
        vm.assume(filler1 != address(0) && filler2 != address(0) && filler1 != filler2);
        vm.assume(filler1 != address(c) && filler2 != address(c));
        nonce = bound(nonce, 0, type(uint256).max);

        MakerWithEIP1271 maker = new MakerWithEIP1271();
        FakeToken baseAsset = new FakeToken();

        c = new PuttyV2("", 0, address(baseAsset));
        vm.warp(1_000_000);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(baseAsset),
            strike: 1,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1 days,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory emptyIds = new uint256[](0);

        // First filler fills the signed order.
        vm.prank(filler1);
        c.fillOrder(order, "", emptyIds);

        uint256 oppositeId = uint256(c.hashOppositeOrder(order));
        uint256 longId = uint256(c.hashOrder(order));

        // Rule: a second fill of the same already-minted order must revert, so ownership of both
        // position ids never changes via re-minting.
        bool ok;
        vm.prank(filler2);
        try c.fillOrder(order, "", emptyIds) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(
            !ok && c.ownerOf(oppositeId) == filler1 && c.ownerOf(longId) == address(maker),
            "remint of existing id must revert and leave owners unchanged"
        );
    }
}

contract MakerWithEIP1271 {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

contract FakeToken {
    fallback() external payable {}
}
